"use no memo";
import React from 'react';
import {
  FlexWidget,
  ImageWidget,
  TextWidget,
} from 'react-native-android-widget';
import type { ColorProp } from 'react-native-android-widget';

import type { WidgetData } from './data';

const NAVBAR: ColorProp  = '#121212';
const CARD: ColorProp    = '#202020';
const TEXT: ColorProp    = '#FFFFFF';
const MUTED: ColorProp   = '#9E9E9E';
const PRIMARY: ColorProp = '#FFC107';
const ACCENT_BG          = '#1A2A00' as ColorProp;

const IMG_HOME      = 'data:image/png;base64,';
const IMG_GAS       = 'data:image/png;base64,';
const IMG_NAV       = 'data:image/png;base64,';
const IMG_ADD       = 'data:image/png;base64,';
const IMG_PLAY      = 'data:image/png;base64,';
const IMG_PAUSE     = 'data:image/png;base64,';
const IMG_STOP      = 'data:image/png;base64,';
const IMG_COFFEE    = 'data:image/png;base64,';
const IMG_CIGARETTE = 'data:image/png;base64,';

const IMG_CAR      = 'data:image/png;base64,';
const IMG_MOTO_VEH = 'data:image/png;base64,';
const IMG_WALK     = 'data:image/png;base64,';

export interface AllInOneWidgetProps extends WidgetData {
  shortcuts: { name: string; lat: number | null; lng: number | null }[];
  tripStatus?: 'idle' | 'selecting' | 'active' | 'paused';
  tripMode?: 'voiture' | 'moto' | 'balade' | null;
  tripDistKm?: number;
  tripElapsedMs?: number;
  spinAngle?: number;
}

function ImgBtn({
  image,
  clickAction,
  bg = CARD,
}: {
  image: string;
  clickAction: string;
  bg?: ColorProp;
}) {
  return (
    <FlexWidget
      clickAction={clickAction}
      style={{
        width: 49,
        height: 49,
        justifyContent: 'center',
        alignItems: 'center',
        backgroundColor: bg,
        borderRadius: 7,
      }}
    >
      <ImageWidget
        image={image as any}
        imageWidth={40}
        imageHeight={40}
        style={{ width: 40, height: 40 }}
      />
    </FlexWidget>
  );
}

function TextBtn({
  label,
  sub,
  clickAction,
  bg = CARD,
}: {
  label: string;
  sub?: string;
  clickAction: string;
  bg?: ColorProp;
}) {
  return (
    <FlexWidget
      clickAction={clickAction}
      style={{
        width: 49,
        height: 49,
        justifyContent: 'center',
        alignItems: 'center',
        backgroundColor: bg,
        borderRadius: 7,
        flexDirection: 'column',
      }}
    >
      <TextWidget
        text={label}
        style={{ fontSize: 11, fontWeight: 'bold', color: TEXT }}
      />
      {sub ? (
        <TextWidget
          text={sub}
          style={{ fontSize: 9, color: MUTED }}
        />
      ) : null}
    </FlexWidget>
  );
}

export function AllInOneWidget({
  tasks,
  widgetAppts,
  todayWork,
  todayDayNum,
  marieCircleColor,
  tripStatus = 'idle',
  tripMode = null,
  tripDistKm = 0,
  tripElapsedMs = 0,
}: AllInOneWidgetProps) {
  const isRepos  = todayWork === 'Repos';
  const nextAppt = widgetAppts[0] ?? null;

  const tripDistStr = tripDistKm.toFixed(2) + ' km';
  const totalMin = Math.floor(tripElapsedMs / 60_000);
  const hh = Math.floor(totalMin / 60);
  const mm = totalMin % 60;
  const tripTimeStr = hh > 0
    ? `${hh}h ${String(mm).padStart(2, '0')}`
    : `${mm} min`;

  return (
    <FlexWidget
      clickAction="OPEN_APP"
      style={{
        height: 'match_parent',
        width: 'match_parent',
        backgroundColor: NAVBAR,
        borderRadius: 14,
        paddingHorizontal: 5,
        paddingTop: 3,
        paddingBottom: 3,
        flexDirection: 'column',
        flexGap: 2,
      }}
    >
      {/* ─── Ligne 1 : infos ─── */}
      <FlexWidget
        style={{
          width: 'match_parent',
          flexDirection: 'row',
          alignItems: 'center',
          height: 24,
          flexGap: 6,
        }}
      >
        {/* Anneau coloré shift Marie — taille contenue dans la row */}
        <FlexWidget
          clickAction="REFRESH"
          style={{
            width: 24,
            height: 24,
            borderRadius: 12,
            backgroundColor: marieCircleColor as ColorProp,
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          <FlexWidget
            style={{
              width: 18,
              height: 18,
              borderRadius: 9,
              backgroundColor: NAVBAR,
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            <TextWidget
              text={String(todayDayNum)}
              style={{ fontSize: 10, fontWeight: 'bold', color: '#FFFFFF' }}
            />
          </FlexWidget>
        </FlexWidget>

        {/* Travail */}
        <TextWidget
          text={isRepos ? 'Repos' : todayWork}
          style={{ fontSize: 11, color: isRepos ? MUTED : PRIMARY, fontWeight: 'bold' }}
          maxLines={1}
          truncate="END"
        />

        {/* Spacer */}
        <FlexWidget style={{ flex: 1, height: 1, backgroundColor: NAVBAR }} />

        {/* Tasks */}
        <TextWidget
          text={`${tasks.length} taches`}
          style={{ fontSize: 10, color: TEXT }}
        />

        {/* Appt */}
        {nextAppt ? (
          <TextWidget
            text={`· ${nextAppt.title}`}
            style={{ fontSize: 10, color: PRIMARY }}
            maxLines={1}
            truncate="END"
          />
        ) : null}
      </FlexWidget>

      {/* ─── Ligne 2 : boutons — flex:1 remplit la hauteur restante ─── */}
      <FlexWidget
        style={{
          flexDirection: 'row',
          width: 'match_parent',
          flex: 1,
          alignItems: 'center',
          flexGap: 4,
        }}
      >
        {/* ── idle : navigation normale + play ── */}
        {tripStatus === 'idle' && (
          <ImgBtn image={IMG_HOME} clickAction="NAVIGATE_HOME" />
        )}
        {tripStatus === 'idle' && (
          <ImgBtn image={IMG_GAS}  clickAction="OPEN_FUEL" />
        )}
        {tripStatus === 'idle' && (
          <ImgBtn image={IMG_NAV}  clickAction="NAVIGATE_TO" />
        )}
        {tripStatus === 'idle' && (
          <ImgBtn image={IMG_ADD}  clickAction="ADD_TRANSACTION" />
        )}
        {tripStatus === 'idle' && (
          <ImgBtn image={IMG_PLAY} clickAction="MANUAL_TRIP_START" bg={ACCENT_BG} />
        )}

        {/* ── selecting : choisir le mode — icônes blanches sur fond coloré ── */}
        {tripStatus === 'selecting' && (
          <ImgBtn image={IMG_CAR}      clickAction="SELECT_MODE_VOITURE" bg={'#2196F3' as ColorProp} />
        )}
        {tripStatus === 'selecting' && (
          <ImgBtn image={IMG_MOTO_VEH} clickAction="SELECT_MODE_MOTO"    bg={'#FF9800' as ColorProp} />
        )}
        {tripStatus === 'selecting' && (
          <ImgBtn image={IMG_WALK}     clickAction="SELECT_MODE_BALADE"   bg={'#4CAF50' as ColorProp} />
        )}

        {/* ── active : Pause | Stop | Nav ── */}
        {tripStatus === 'active' && (
          <ImgBtn image={IMG_PAUSE} clickAction="MANUAL_TRIP_PAUSE" />
        )}
        {tripStatus === 'active' && (
          <ImgBtn image={IMG_STOP} clickAction="MANUAL_TRIP_END" />
        )}
        {tripStatus === 'active' && (
          <ImgBtn image={IMG_NAV} clickAction="NAVIGATE_TO" />
        )}

        {/* ── paused : Resume | Stop | Nav ── */}
        {tripStatus === 'paused' && (
          <ImgBtn image={IMG_PLAY} clickAction="MANUAL_TRIP_RESUME" bg={ACCENT_BG} />
        )}
        {tripStatus === 'paused' && (
          <ImgBtn image={IMG_STOP} clickAction="MANUAL_TRIP_END" />
        )}
        {tripStatus === 'paused' && (
          <ImgBtn image={IMG_NAV} clickAction="NAVIGATE_TO" />
        )}

        {/* Séparateur + café + cig — idle et selecting uniquement */}
        {(tripStatus === 'idle' || tripStatus === 'selecting') && (
          <FlexWidget
            style={{ width: 8, height: 'match_parent', backgroundColor: NAVBAR }}
          />
        )}
        {(tripStatus === 'idle' || tripStatus === 'selecting') && (
          <ImgBtn image={IMG_COFFEE}    clickAction="ADD_COFFEE" />
        )}
        {(tripStatus === 'idle' || tripStatus === 'selecting') && (
          <ImgBtn image={IMG_CIGARETTE} clickAction="ADD_CIGARETTE" />
        )}

        {/* ── active/paused : bloc infos trajet ── */}
        {(tripStatus === 'active' || tripStatus === 'paused') && (
          <FlexWidget
            style={{
              flex: 1,
              height: 'match_parent',
              backgroundColor: CARD,
              borderRadius: 7,
              justifyContent: 'center',
              alignItems: 'center',
              flexDirection: 'column',
            }}
          >
            <TextWidget
              text={tripDistStr}
              style={{ fontSize: 13, fontWeight: 'bold', color: PRIMARY }}
            />
            <TextWidget
              text={tripTimeStr}
              style={{ fontSize: 11, color: TEXT }}
            />
          </FlexWidget>
        )}
      </FlexWidget>
    </FlexWidget>
  );
}
